import { cva, type VariantProps } from "class-variance-authority"

export const inputVariants = cva(
  "h-8 w-full min-w-0 rounded-lg border border-input bg-transparent px-2.5 py-1 text-base transition-colors outline-none file:inline-flex file:h-6 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:cursor-not-allowed disabled:bg-input/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 md:text-sm dark:bg-input/30 dark:disabled:bg-input/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&[readonly]]:border-border [&[readonly]]:bg-muted",
  {
    variants: {
      variant: {
        outline:
          "border-border hover:border-input disabled:bg-muted dark:disabled:bg-muted",
        filled: "border-border bg-muted hover:border-input dark:bg-muted",
        underline:
          "rounded-none border-0 border-b border-input bg-transparent px-0 dark:bg-transparent",
        ghost:
          "border-transparent bg-transparent hover:bg-muted/50 dark:bg-transparent",
      },
    },
    defaultVariants: { variant: "outline" },
  }
)

export type InputVariants = VariantProps<typeof inputVariants>
export type InputVariant = NonNullable<InputVariants["variant"]>

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
} from "@angular/core"

import { cn } from "@/lib/utils"

import { inputVariants, type InputVariant } from "./input.variants"

/**
 * Angular port of @force-ui/input (radix-force-ui style).
 *
 * Attribute selector on a native <input> — usage:
 *   <input uiInput type="email" placeholder="m@example.com" />
 *   <input uiInput variant="filled" />
 *
 * Four variants: outline (default), filled, underline, ghost.
 * See DIVERGENCES.md for notes on the tiered border approach.
 */
@Component({
  selector: "input[uiInput]",
  standalone: true,
  template: "",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    "data-slot": "input",
    "[attr.data-variant]": "variant()",
    "[class]": "classes()",
  },
})
export class InputComponent {
  readonly variant = input<InputVariant>("outline")
  readonly className = input<string | undefined>(undefined, { alias: "class" })

  protected readonly classes = computed(() =>
    cn(inputVariants({ variant: this.variant() }), this.className())
  )
}

export { InputComponent as Input } from "./input.component"
export {
  inputVariants,
  type InputVariants,
  type InputVariant,
} from "./input.variants"
